style.css:
@-moz-document domain("youtube.com") {
body {
    background-color: #0f0f0f !important;
    color: #ffffff !important;
  }

  ytd-app {
    background-color: #1e1e1e !important;
  }

  #container.ytd-masthead,
  ytd-mini-guide-renderer,
  ytd-guide-renderer {
    background: linear-gradient(135deg, #ff00cc, #3333ff) !important;
  }

  a,
  yt-formatted-string,
  .title,
  .style-scope.ytd-video-primary-info-renderer {
    color: #00ffff !important;
  }

  ytd-thumbnail,
  ytd-video-renderer {
    border-radius: 10px !important;
    box-shadow: 0 0 10px #00ffffaa;
    transition: transform 0.3s ease;
  }

  ytd-video-renderer:hover {
    transform: scale(1.03);
  }
}

@-moz-document domain("google.com") {
body {
    background-color: #1a1a2e !important;
    color: #ffffff !important;
  }

  input,
  textarea {
    background-color: #0f3460 !important;
    color: #ffffff !important;
    border: 1px solid #e94560 !important;
  }

  a {
    color: #03dac6 !important;
  }

  .gb_Se,
  .gb_Ba {
    background: linear-gradient(135deg, #ff6ec4, #7873f5) !important;
    color: #ffffff !important;
  }

  .FPdoLc.lJ9FBc input {
    background-color: #e94560 !important;
    color: white !important;
  }

  .FPdoLc.lJ9FBc input:hover {
    background-color: #ff6b81 !important;
  }
}
